//! Cross-check Rust's independent evaluator against fixture rows
//! generated by the Lean evaluator and grounded in evalCNF_impose_iff.
//! The test runs only with the explicit 'lean-interop' feature in CI.

use std::fs;

#[derive(Clone, Copy, Debug)]
struct Literal {
    variable: usize,
    positive: bool,
}

fn read_formula(encoded: &str) -> Vec<Vec<Literal>> {
    if encoded == "~" {
        return Vec::new();
    }
    encoded
        .split(';')
        .map(|clause| {
            if clause == "_" {
                return Vec::new();
            }
            clause
                .split(',')
                .map(|token| {
                    let signed: i32 = token.parse().expect("valid signed literal");
                    assert_ne!(signed, 0, "zero is not a literal");
                    let variable = signed.unsigned_abs() as usize - 1;
                    assert!(variable < 4, "out-of-domain variable in fixture");
                    Literal {
                        variable,
                        positive: signed > 0,
                    }
                })
                .collect()
        })
        .collect()
}

fn eval_formula(formula: &[Vec<Literal>], assignment: &[bool; 4]) -> bool {
    formula.iter().all(|clause| {
        clause
            .iter()
            .any(|literal| assignment[literal.variable] == literal.positive)
    })
}

fn read_bool(text: &str) -> bool {
    match text {
        "true" => true,
        "false" => false,
        _ => panic!("invalid Lean Bool: {text}"),
    }
}

#[test]
fn lean_rust_semantics() {
    let path = std::env::var("PVSNP_LEAN_FIXTURES")
        .expect("CI must provide fixtures generated by the Lean evaluator");
    let content = fs::read_to_string(path).expect("read Lean-generated fixture file");
    let mut rows = content.lines();
    assert_eq!(
        rows.next(),
        Some("seed\tmask\tvariable\tbit\tcnf\tbefore\tafter"),
        "fixture header must match the cross-language protocol"
    );
    let mut checked = 0_usize;
    let mut original_true = 0_usize;
    let mut original_false = 0_usize;

    for line in rows {
        let fields: Vec<_> = line.split('\t').collect();
        assert_eq!(fields.len(), 7, "malformed row: {line}");
        let seed: usize = fields[0].parse().expect("seed");
        let mask: usize = fields[1].parse().expect("assignment mask");
        let variable: usize = fields[2].parse().expect("variable");
        assert!(variable < 4);
        let bit = read_bool(fields[3]);
        let formula = read_formula(fields[4]);
        let expected_original = read_bool(fields[5]);
        let expected_restricted = read_bool(fields[6]);
        let assignment = std::array::from_fn(|i| ((mask >> i) & 1) == 1);

        let actual_original = eval_formula(&formula, &assignment);
        assert_eq!(
            actual_original, expected_original,
            "Lean/Rust mismatch before restriction at seed={seed}, mask={mask}"
        );

        let mut restricted = formula.clone();
        restricted.insert(
            0,
            vec![Literal {
                variable,
                positive: bit,
            }],
        );
        let actual_restricted = eval_formula(&restricted, &assignment);
        assert_eq!(
            actual_restricted, expected_restricted,
            "Lean/Rust mismatch after restriction at seed={seed}, mask={mask}"
        );
        assert_eq!(
            actual_restricted,
            actual_original && assignment[variable] == bit,
            "restriction semantics failed at seed={seed}, mask={mask}"
        );
        if actual_original {
            original_true += 1;
        } else {
            original_false += 1;
        }
        checked += 1;
    }
    assert!(checked >= 1000, "insufficient differential coverage");
    assert!(original_true > 0 && original_false > 0, "both SAT and UNSAT evaluations required");
    println!("Validated {checked} Lean/Rust restriction evaluations");
}
